BEGIN;
CREATE TEMP TABLE phase_fixture AS SELECT user_id owner_id,partner_user_id partner_id,gen_random_uuid() account_id,gen_random_uuid() untouched FROM partner_links WHERE status='active' LIMIT 1;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM phase_fixture) THEN RAISE EXCEPTION 'Active pair required';END IF;END $$;
GRANT SELECT ON phase_fixture TO authenticated;
INSERT INTO accounts(id,user_id,name,type,current_balance,currency) SELECT account_id,owner_id,'Lifecycle fixture','checking',1000,'USD' FROM phase_fixture UNION ALL SELECT untouched,owner_id,'Untouched fixture','savings',2000,'USD' FROM phase_fixture;
SET LOCAL ROLE authenticated;
DO $$ DECLARE f record;r finance_allocations;e jsonb;event_id uuid;blocked boolean;BEGIN
 SELECT * INTO f FROM phase_fixture;PERFORM set_config('request.jwt.claim.sub',f.owner_id::text,true);
 SELECT * INTO r FROM finance_allocations WHERE account_id=f.account_id ORDER BY effective_from DESC LIMIT 1;
 e:=jsonb_build_array(jsonb_build_object('account_id',f.account_id,'expense_pct',100,'balance_pct',NULL,'expected_id',r.id,'expected_expense',r.owner_pct,'expected_balance',coalesce(r.balance_pct,r.owner_pct)));
 PERFORM finance_apply_lifecycle('single',current_date-60,e,false);
 SELECT * INTO r FROM finance_allocations WHERE account_id=f.account_id ORDER BY effective_from DESC LIMIT 1;
 e:=jsonb_build_array(jsonb_build_object('account_id',f.account_id,'expense_pct',50,'balance_pct',NULL,'expected_id',r.id,'expected_expense',r.owner_pct,'expected_balance',coalesce(r.balance_pct,r.owner_pct)));
 PERFORM finance_apply_lifecycle('sharing',current_date-30,e,false);
 IF (SELECT balance_pct FROM finance_allocations WHERE account_id=f.account_id AND effective_from=current_date-30)<>100 THEN RAISE EXCEPTION 'Sharing silently pooled balances';END IF;
 blocked:=false;BEGIN PERFORM finance_apply_lifecycle('merged',current_date,e,false);EXCEPTION WHEN raise_exception THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Stale preview accepted';END IF;
 PERFORM finance_category_split(f.account_id,'Rent',current_date-20,60);
 SELECT * INTO r FROM finance_allocations WHERE account_id=f.account_id ORDER BY effective_from DESC LIMIT 1;
 e:=jsonb_build_array(jsonb_build_object('account_id',f.account_id,'expense_pct',50,'balance_pct',50,'expected_id',r.id,'expected_expense',r.owner_pct,'expected_balance',coalesce(r.balance_pct,r.owner_pct)));
 event_id:=finance_apply_lifecycle('merged',current_date,e,true);
 IF (SELECT balance_pct FROM finance_allocations WHERE account_id=f.account_id AND effective_from=current_date)<>50 THEN RAISE EXCEPTION 'Explicit pooling failed';END IF;
 IF (SELECT owner_pct FROM finance_allocations WHERE account_id=f.account_id AND effective_from=current_date-60)<>100 THEN RAISE EXCEPTION 'Single history rewritten';END IF;
 IF (SELECT owner_pct FROM finance_category_splits WHERE account_id=f.account_id AND effective_from=current_date-20)<>60 OR (SELECT owner_pct FROM finance_category_splits WHERE account_id=f.account_id AND effective_from=current_date)<>50 THEN RAISE EXCEPTION 'Dated category reset failed';END IF;
 IF (SELECT count(*) FROM finance_allocations WHERE account_id=f.untouched)<>1 THEN RAISE EXCEPTION 'Unselected account changed';END IF;
 IF (SELECT current_balance FROM accounts WHERE id=f.account_id)<>1000 THEN RAISE EXCEPTION 'Bank balance changed';END IF;
 IF EXISTS(SELECT 1 FROM finance_account_sharing WHERE account_id=f.account_id AND enabled) THEN RAISE EXCEPTION 'Access unexpectedly granted';END IF;
 IF NOT EXISTS(SELECT 1 FROM finance_documents d JOIN finance_lifecycle_events l ON l.scope_id=d.id WHERE l.id=event_id AND d.kind='scope') THEN RAISE EXCEPTION 'Fixed scope not saved';END IF;
 PERFORM set_config('request.jwt.claim.sub',f.partner_id::text,true);
 IF EXISTS(SELECT 1 FROM finance_lifecycle_events WHERE id=event_id AND owner_id=f.owner_id) THEN RAISE EXCEPTION 'Private event exposed';END IF;
 blocked:=false;BEGIN PERFORM finance_apply_lifecycle('merged',current_date,e,false);EXCEPTION WHEN raise_exception THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Another person changed the account';END IF;
END $$;
RESET ROLE;
ROLLBACK;
SELECT 'PASS: dated lifecycle changes, historical preservation, explicit pooling, category boundaries, fixed scope, stale-preview rejection, privacy and owner-only mutation. Fixtures rolled back.' AS result;
